<script setup lang="ts">
import { computed } from 'vue'
import recorded from '../data/manual-evaluation.json'
import type { ManualEvaluation as EvaluationReport } from '../lib/manual-metrics.mjs'
import corpus from '../data/manual-corpus.json'
import { useManualPlayback } from '../lib/manual-motion'
const report: EvaluationReport = recorded
const { index, playing, reduced, pulse, version, select, stop, replay } = useManualPlayback(() => report.rows.length, 16)
const current = computed(() => report.rows[index.value]!)
const sectionTitle = (reference: string) => { const [manual, section] = reference.split('#'); return corpus.find(item => item.id === manual)?.sections.find(item => item.id === section)?.title ?? reference }
const verdict = computed(() => current.value.kind === 'positive' ? current.value.hitAtK ? 'Relevant section found' : 'Relevant section missed' : current.value.falsePositive ? 'Lexical false positive' : 'No result · expected')
const groups = [{ label: 'Positive queries', start: 0, rows: report.rows.slice(0, 18) }, { label: 'Negative / unsupported queries', start: 18, rows: report.rows.slice(18) }]
function outcome(row: typeof report.rows[number]) { return row.kind === 'positive' ? row.hitAtK ? 'hit' : 'miss' : row.falsePositive ? 'false positive' : 'empty' }
</script>
<template>
  <div class="manual-demo" data-testid="manual-evaluation" :data-playing="playing"><div class="manual-demo-heading"><p>Interactive evaluation · saved 26-query benchmark</p><h3>Keep the miss. Keep the false matches.</h3></div><div class="manual-evaluation-totals"><div><strong>17 / 18</strong><span>positive queries hit at rank 1</span><small>MRR · recall@5 · hit@5 = 0.944444</small></div><div><strong>4 / 8</strong><span>negative queries return lexical matches</span><small>False-positive rate = 50%</small></div></div><div v-for="group in groups" :key="group.label" class="manual-query-group"><h4>{{ group.label }}</h4><div class="manual-query-tiles" role="group" :aria-label="group.label"><button v-for="(row, position) in group.rows" :key="row.id" type="button" :data-query-id="row.id" :aria-label="`${row.id}: ${row.query} · ${outcome(row)}`" :aria-pressed="index === group.start + position" :class="{ warning: outcome(row) === 'miss' || row.falsePositive }" @click="select(group.start + position)"><span>{{ row.id }}</span><strong aria-hidden="true">{{ outcome(row) === 'hit' ? '✓' : outcome(row) === 'empty' ? '∅' : '!' }}</strong></button></div></div><p class="manual-tile-key">✓ relevant hit · ∅ expected empty · ! miss or lexical false positive</p>
    <div class="manual-evaluation-inspector" :aria-live="playing ? 'off' : 'polite'"><div class="manual-evaluation-query"><span>{{ current.id }} · {{ current.kind }}</span><h4 data-testid="manual-eval-query">{{ current.query }}</h4><strong data-testid="manual-eval-outcome">{{ verdict }}</strong></div><div class="manual-label-comparison" :class="{ 'is-tracing': pulse }"><div><h4>Project-authored relevance labels</h4><ul v-if="current.relevant.length"><li v-for="reference in current.relevant" :key="reference"><strong>{{ sectionTitle(reference) }}</strong><code>{{ reference }}</code></li></ul><p v-else>No section is labelled as answering this question.</p></div><div class="manual-eval-connector" aria-hidden="true"><svg :key="version" viewBox="0 0 56 42"><path d="M2 12h50 M44 5l8 7-8 7 M54 30H4 M12 23l-8 7 8 7" /></svg><span>Compare</span></div><div><h4>Retrieved top {{ report.k }}</h4><ol v-if="current.returned.length" data-testid="manual-eval-returned"><li v-for="reference in current.returned.slice(0, report.k)" :key="reference" :class="{ relevant: current.relevant.includes(reference) }"><strong>{{ sectionTitle(reference) }}</strong><code>{{ reference }}</code><span>{{ current.relevant.includes(reference) ? 'Labelled relevant' : 'No relevance label' }}</span></li></ol><p v-else data-testid="manual-eval-returned">No lexical results.</p></div></div><div class="manual-eval-metrics" data-testid="manual-eval-metrics"><template v-if="current.kind === 'positive'"><span>First relevant rank <strong>{{ current.firstRelevantRank ?? 'Not found' }}</strong></span><span>Reciprocal rank <strong>{{ current.reciprocalRank }}</strong></span><span>Recall@5 / hit@5 <strong>{{ current.recallAtK }} / {{ current.hitAtK }}</strong></span></template><template v-else><span>Negative denominator <strong>8 queries</strong></span><span>Any returned result? <strong>{{ current.falsePositive ? 'Yes · false positive' : 'No · expected empty' }}</strong></span></template></div><p v-if="current.id === 'p17'" class="manual-eval-note">“Readings” matches the missing-samples paragraph. The intended CSV export section is absent, so this positive query contributes zero to all three positive metrics.</p><p v-else-if="current.falsePositive" class="manual-eval-note">These returned sections share vocabulary with an unsupported question. Their scores do not establish that they answer it; this query contributes to the negative false-positive count.</p><p v-else class="manual-eval-note">Positive metrics include every positive query, including misses. Negative queries use a separate denominator and never inflate positive retrieval metrics.</p></div>
    <div class="manual-controls"><button type="button" @click="playing ? stop() : replay()">{{ playing ? 'Pause evaluation' : 'Replay query set' }}</button><button type="button" :disabled="index === 0" @click="select(index - 1)">Previous query</button><button type="button" :disabled="index === report.rows.length - 1" @click="select(index + 1)">Next query</button><span>{{ index + 1 }} / {{ report.rows.length }}</span></div><p class="manual-demo-note">{{ reduced ? 'Reduced motion: select a query manually. ' : 'Playback follows the saved query order at an illustrative pace. ' }}Selection does not change the benchmark denominator. All labels are project-authored on fictional data; this is not an independent benchmark.</p></div>
</template>
